const LANG_NAMES={en:'English',es:'Español',de:'Deutsch',fr:'Français',it:'Italiano',nl:'Nederlands',pt:'Português'};
const PHONE='34615788239';
const q=s=>document.querySelector(s),qa=s=>[...document.querySelectorAll(s)];
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const wa=text=>'https://wa.me/'+PHONE+'?text='+encodeURIComponent(text);
let lang='en',lastTrigger=null;
try{const saved=new URLSearchParams(location.search).get('lang')||localStorage.getItem('sumatra-language')||navigator.language.split('-')[0];if(UI[saved])lang=saved}catch{}
const t=key=>UI[lang][key];
const price=value=>new Intl.NumberFormat(lang,{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(value);
for(const [code,value]of Object.entries({en:'Privacy',es:'Privacidad',de:'Datenschutz',fr:'Confidentialité',it:'Privacy',nl:'Privacy',pt:'Privacidade'}))UI[code].privacyLabel=value;
function duration(route){return route.hours?route.hours+' '+t('hours'):route.days+' '+(route.days===1?t('daySingular'):t('days'))}
function factline(route){return duration(route)+(route.nights?' · '+route.nights+' '+(route.nights===1?t('night'):t('nights')):'')}
function compactCard(i){const route=ROUTES[i],r=R[lang][i];return `<article class="compact-tour"><img src="assets/${route.img}" alt="${escapeHTML(r[0])}" width="200" height="170" loading="lazy"><div><h3>${escapeHTML(r[0])}</h3><p>${escapeHTML(factline(route))} · ${escapeHTML(t('from'))} ${price(route.price)}</p><button data-route="${i}">${escapeHTML(t('viewRoute'))}</button></div></article>`}
function renderRoutes(){q('#tour-grid').innerHTML=[0,1,2].map(i=>{const route=ROUTES[i],r=R[lang][i];return `<article class="tour-card"><div class="tour-photo"><img src="assets/${route.img}" alt="${escapeHTML(r[0])}" loading="lazy" width="600" height="450"><span class="tag">${escapeHTML(duration(route))}</span>${i===1?`<span class="pick">${escapeHTML(t('bestPick'))}</span>`:''}</div><div class="card-body"><div class="tour-facts"><span>BUKIT LAWANG</span><span>${escapeHTML(factline(route))}</span></div><h3>${escapeHTML(r[0])}</h3><p>${escapeHTML(r[1])}</p><div class="card-bottom"><div class="price"><small>${escapeHTML(t('from'))}</small><strong>${price(route.price)}</strong></div><button data-route="${i}">${escapeHTML(t('viewRoute'))}</button></div></div></article>`}).join('');q('#local-grid').innerHTML=[3,4,5,6].map(compactCard).join('');q('#beyond-grid').innerHTML=[7,9,8].map(i=>{const route=ROUTES[i],r=R[lang][i];return `<article class="destination"><img src="assets/${route.img}" alt="${route.place}" width="600" height="400" loading="lazy"><div class="destination-body"><div><h3>${escapeHTML(r[0])}</h3><p>${escapeHTML(duration(route))} · ${escapeHTML(t('from'))} ${price(route.price)}</p></div><button data-route="${i}" aria-label="${escapeHTML(t('viewRoute')+' '+r[0])}">↗</button></div></article>`}).join('');q('#other-grid').innerHTML=[10,11].map(compactCard).join('');qa('[data-route]').forEach(b=>b.addEventListener('click',()=>openRoute(Number(b.dataset.route),b)))}
const CREDITS=[['Lake Toba','Bisajunisa','Lake_Toba_and_the_surrounding_hills.jpg','4.0'],['Bukit Lawang','Abang Senja','Sungai_di_Bukit_Lawang.jpg','4.0'],['Orangutan','Andreiromario','Orang_Utan_Sumatera_Bukit_Lawang.jpg','4.0'],['Orangutan','HaidirAndiNovianto','Orangutan_Sumatra_di_Bukit_Lawang.jpg','4.0'],['Harau','algenta101','Harau_valley.jpg','by2'],['Kerinci','Firdausjuanda06','Gunung_Kerinci.jpg','4.0'],['Mentawai','Itscaptainkeels','Katiet,_Sipora,_Mentawai.jpg','by4']];
function applyLanguage(){document.documentElement.lang=lang;q('#language').value=lang;document.title='Explore Sumatra Escape — '+t('navRoutes')+' · Bukit Lawang';qa('[data-t]').forEach(el=>{const key=el.dataset.t;if(!UI[lang][key])throw new Error('Missing '+lang+':'+key);if(['hero','routesTitle','enquiryTitle','teamTitle'].includes(key))el.innerHTML=t(key);else el.textContent=t(key)});q('#language').setAttribute('aria-label',t('messageLanguage'));q('nav').setAttribute('aria-label',t('navRoutes'));q('.close-dialog').setAttribute('aria-label',t('close'));const tourValue=q('#tour').value;q('#tour').innerHTML=ROUTES.map((r,i)=>`<option value="${i}">${escapeHTML(R[lang][i][0])} · ${r.id}</option>`).join('')+`<option value="custom">${escapeHTML(t('custom'))}</option>`;if(tourValue)q('#tour').value=tourValue;renderRoutes();renderCommunity();['#phone','#floating-chat'].forEach(s=>q(s).href=wa(t('messageHello')));q('#share-story').href=wa(t('storyMessage'));q('#notes').placeholder=t('notesLabel');q('#credits').innerHTML=CREDITS.map(([place,name,file,license])=>`${place}: <a href="https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file)}" target="_blank" rel="noopener">${name}</a> (<a href="https://creativecommons.org/licenses/${license.startsWith('by')?'by/'+(license==='by4'?'4.0':'2.0'):'by-sa/'+license}/" target="_blank" rel="noopener">CC ${license.startsWith('by')?'BY '+(license==='by4'?'4.0':'2.0'):'BY-SA '+license}</a>)`).join(' · ')+'. '+escapeHTML(t('photoCreditNote'));try{localStorage.setItem('sumatra-language',lang);const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u)}catch{}}
function openRoute(i,trigger){lastTrigger=trigger;const route=ROUTES[i],r=R[lang][i];const note=route.local?t('trekPriceNote'):t('priceNote');q('#tour-detail').innerHTML=`<article class="detail"><div class="eyebrow">${route.id} · ${route.coord}</div><h2 id="detail-title">${escapeHTML(r[0])}</h2><p>${escapeHTML(r[1])}</p><div class="detail-facts"><span>${escapeHTML(factline(route))}</span><span>${escapeHTML(t('level'))} ${route.level}/4</span><span>${escapeHTML(t('from'))} ${price(route.price)} · ${escapeHTML(t('perPerson'))}</span></div><img class="detail-photo" src="assets/${route.img}" alt="${escapeHTML(r[0])}"><h3>${escapeHTML(t('best'))}</h3><p>${escapeHTML(r[2])}</p><h3>${escapeHTML(t('itinerary'))}</h3><ul>${r[3].split('|').map(line=>`<li>${escapeHTML(t('day'))} ${escapeHTML(line)}</li>`).join('')}</ul><h3>${escapeHTML(t('includes'))}</h3><ul>${r[4].split('|').map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul><h3>${escapeHTML(t('excludes'))}</h3><ul>${r[5].split('|').map(line=>`<li>${escapeHTML(line)}</li>`).join('')}</ul>${route.local?`<p class="small">${escapeHTML(TREK_COPY[lang].note)} ${escapeHTML(t('trekTerms'))}</p>`:''}<p class="small">${escapeHTML(note)}</p><button class="button primary" id="choose-route">${escapeHTML(route.local?t('book'):t('askRoute')+' ↗')}</button></article>`;q('#tour-dialog').setAttribute('aria-labelledby','detail-title');q('#tour-dialog').showModal();document.body.classList.add('modal-open');q('#tour-dialog').scrollTop=0;q('#choose-route').addEventListener('click',()=>{q('#tour').value=String(i);q('#tour-dialog').close();q('#enquiry').scrollIntoView({behavior:'smooth'});setTimeout(()=>q('#date').focus({preventScroll:true}),350)})}
q('#language').addEventListener('change',e=>{lang=e.target.value;applyLanguage()});q('.close-dialog').addEventListener('click',()=>q('#tour-dialog').close());q('#tour-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');if(lastTrigger?.isConnected)lastTrigger.focus({preventScroll:true})});q('#tour-dialog').addEventListener('click',e=>{if(e.target===q('#tour-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
const now=new Date();q('#date').min=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');
function enquiryURL(){const value=q('#tour').value;const index=value==='custom'?-1:Number(value);const route=index<0?t('custom'):R[lang][index][0]+' · '+ROUTES[index].id;const lines=[t('messageHello'),'',t('tourLabel')+': '+route,t('messageDate')+': '+q('#date').value,t('messagePeople')+': '+q('#travellers').value,t('messageName')+': '+q('#name').value.trim(),t('messageLanguage')+': '+LANG_NAMES[lang]];if(q('#notes').value.trim())lines.push(t('messageNotes')+': '+q('#notes').value.trim());return wa(lines.join('\n'))}
q('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();if(!e.currentTarget.reportValidity())return;const link=document.createElement('a');link.href=enquiryURL();link.target='_blank';link.rel='noopener';document.body.append(link);link.click();link.remove()});
applyLanguage();
